#include <stdio.h>
int main(void)
{
    int a[3][3]={{999,4,2},{4,999,1},{2,1,999}},key[3]={0,999,999};
    int used[3]={0},total=0;
    for(int step=0;step<3;step++) {
        int u=-1;
        for(int v=0;v<3;v++) { if(!used[v] && (u==-1 || key[v]<key[u])) { u=v; } }
        used[u]=1;total+=key[u];
        for(int v=0;v<3;v++) {
            if(!used[v] && a[u][v]<key[v]) { key[v]=a[u][v]; }
        }
    }
    (void)total;
    printf("%d\n",total);
    return 0;
}

